SELECT t.rec_id AS record_id,t."启用" AS "启用",t."更新时间" AS "更新时间",t."权限代码" AS "权限代码",t."角色名称" AS "角色名称",t."角色编码" AS "角色编码" FROM "Roles" AS t INNER JOIN "Members" AS access_member ON (access_member."用户").id = CURRENT_USER_ID() LEFT JOIN "Roles" AS access_role ON access_member."角色编码" = access_role."角色编码" WHERE (access_member."状态").name = '启用' AND ((access_member."角色编码" IS NULL AND (access_member."角色").name IN ('管理员')) OR (access_role."启用" = TRUE AND access_role."权限代码" LIKE '%|admin.roles|%')) ORDER BY t.rec_id ASC LIMIT 500 OFFSET $1